def get(data, path, default=None):
    cur = data
    for seg in path.split("."):
        if isinstance(cur, dict):
            if seg not in cur:
                return default
            cur = cur[seg]
        elif isinstance(cur, list):
            if not seg.isdigit():
                return default
            idx = int(seg)
            if idx >= len(cur):
                return default
            cur = cur[idx]
        else:
            return default
    return cur
